namespace EFootwear.BLL.Parties.Contracts;

/// <summary>
/// New Party (docx 3.1). The code is generated by the server. A staff party also needs the store the person works in. Fields
/// the schema has no column for (Urdu father name, Urdu address, notes) are kept with the party as extra attributes.
/// </summary>
public sealed record CreatePartyRequest(
    string Name,
    string? NameUrdu,
    string? FatherName,
    string? FatherNameUrdu,
    string? Cnic,
    Guid? CityId,
    string? PrimaryPhone,
    string? SecondaryPhone,
    string? Email,
    string? Address,
    string? AddressUrdu,
    string? Notes,
    bool IsCustomer,
    bool IsVendor,
    bool IsStaff,
    long? CreditLimit,
    string StatusCode,
    string? Designation,
    bool IsManager,
    Guid? StaffStoreId,
    PartyOpeningBalanceRequest? OpeningBalance) : IPartyEditableFields;
